import { Group, Mesh, MeshStandardNodeMaterial, ExtrudeGeometry, Shape, DirectionalLight, Color, Vector3, DoubleSide } from 'three/webgpu';
import { uv, vec3, mix, color as tslColor, float, uniform, modelWorldMatrix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const totalWidth = cols * tileWidth + (cols - 1) * gap;
  const totalHeight = rows * tileHeight + (rows - 1) * gap;
  const startX = -totalWidth / 2 + tileWidth / 2;
  const startY = totalHeight / 2 - tileHeight / 2;

  // Shared rounded rectangle geometry with chamfered edges
  const shape = new Shape();
  const r = 0.02;
  const w = tileWidth / 2;
  const h = tileHeight / 2;
  shape.moveTo(-w + r, -h);
  shape.lineTo(w - r, -h);
  shape.quadraticCurveTo(w, -h, w, -h + r);
  shape.lineTo(w, h - r);
  shape.quadraticCurveTo(w, h, w - r, h);
  shape.lineTo(-w + r, h);
  shape.quadraticCurveTo(-w, h, -w, h - r);
  shape.lineTo(-w, -h + r);
  shape.quadraticCurveTo(-w, -h, -w + r, -h);
  const geometry = new ExtrudeGeometry(shape, {
    depth: 0.02,
    bevelEnabled: true,
    bevelSize: 0.02,
    bevelThickness: 0.02,
    bevelSegments: 3,
  });
  geometry.center();

  // Shared material with anisotropic brushed metal and vertical albedo ramp
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.55;
  material.metalness = 0.5;
  material.clearcoat = 0.2;
  material.anisotropy = 0.6;
  material.anisotropyRotation = 0;
  material.side = DoubleSide;

  // Albedo ramp: #1a1a22 at bottom (y=0) -> #121218 at top (y=1)
  const colorBottom = tslColor(new Color(0x1a1a22));
  const colorTop = tslColor(new Color(0x121218));
  material.colorNode = mix(colorBottom, colorTop, uv().y);

  // Directional light to create anisotropic highlight
  const light = new DirectionalLight(0xffffff, 0.8);
  light.position.set(1, 1, 1).normalize();
  light.target.position.set(0, 0, 0);
  group.add(light);
  group.add(light.target);

  // Parse text content
  const items = config.textContent ?? [];
  const kickerItem = items[0];
  const brandItems = items.slice(1, 7);

  // Create kicker text
  if (kickerItem) {
    const kickerY = startY + tileHeight / 2 + 0.3;
    const kickerText = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0.12 * 9,
    });
    kickerText.position.set(0, kickerY, 0);
    group.add(kickerText);
  }

  // Create tiles
  const tileGroups = [];
  const timelines = [];

  brandItems.forEach((brand, index) => {
    const col = index % cols;
    const row = Math.floor(index / cols);
    const x = startX + col * (tileWidth + gap);
    const y = startY - row * (tileHeight + gap);

    // Tile group
    const tileGroup = new Group();
    tileGroup.position.set(x, y, 0);

    // Mesh
    const mesh = new Mesh(geometry, material);
    tileGroup.add(mesh);

    // Wordmark text
    const text = ctx.fontAtlas.createText(brand.text, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0.08 * 13,
    });
    // Assume first child is the actual text mesh
    const textMesh = text.isMesh ? text : text.children[0];
    if (textMesh && textMesh.material) {
      textMesh.material = textMesh.material.clone();
      textMesh.material.transparent = true;
      textMesh.material.opacity = 0.78;
    }
    text.position.set(0, 0, 0.01);
    tileGroup.add(text);

    // Store references for hover animation
    tileGroup.userData.textMesh = textMesh;
    tileGroup.userData.initialZ = 0;

    // Hover animations
    const hoverIn = gsap.to(
      { tileGroup, textMesh },
      {
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        paused: true,
        onUpdate() {
          if (textMesh && textMesh.material) {
            textMesh.material.opacity = this.progress() * (1.0 - 0.78) + 0.78;
          }
          tileGroup.position.z = this.progress() * 0.05;
        },
      }
    );
    const hoverOut = gsap.to(
      { tileGroup, textMesh },
      {
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        paused: true,
        onUpdate() {
          if (textMesh && textMesh.material) {
            textMesh.material.opacity = (1 - this.progress()) * (1.0 - 0.78) + 0.78;
          }
          tileGroup.position.z = (1 - this.progress()) * 0.05;
        },
      }
    );

    tileGroup.userData.handlers = {
      pointerover: (e) => {
        hoverIn.restart();
        hoverOut.pause();
      },
      pointerout: (e) => {
        hoverOut.restart();
        hoverIn.pause();
      },
    };

    group.add(tileGroup);
    tileGroups.push(tileGroup);

    // Stagger entrance animation
    const entrance = gsap.fromTo(
      tileGroup,
      { opacity: 0, y: tileGroup.position.y + 0.2 },
      {
        opacity: 1,
        y: tileGroup.position.y,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay: index * 0.08,
      }
    );
    timelines.push(entrance);
  });

  // Cleanup
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach(t => t.kill());
    // Remove event listeners
    tileGroups.forEach(tg => {
      tg.userData.handlers = null;
    });
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Remove children (lights, text objects)
    while (group.children.length > 0) {
      const child = group.children[0];
      if (child.isLight) {
        // dispose light?
      }
      if (child.isObject3D) {
        child.traverse((node) => {
          if (node.isMesh) {
            node.geometry?.dispose();
            node.material?.dispose();
          }
        });
      }
      group.remove(child);
    }
  };

  return group;
}
